const updateLimitAssignment = `-- name: UpdateLimitAssignment :execrows
UPDATE limit_assignment a
   SET profile_id = p.id, overrides = $1::text::jsonb, capped = $2, note = $3,
       version = a.version + 1, updated_at = now(), updated_by = NULLIF($4::text, '')::uuid
  FROM limit_profile p
 WHERE p.key = $5 AND a.id = $6::text::uuid AND a.version = $7
`

