const upsertLimitCeiling = `-- name: UpsertLimitCeiling :exec
INSERT INTO limit_ceiling (repository_id, class, uncached_bytes_per_hour, upstream_requests_per_hour, updated_by)
VALUES ($1, $2, NULLIF($3::bigint, 0),
        NULLIF($4::bigint, 0), NULLIF($5::text, '')::uuid)
ON CONFLICT (repository_id, class) DO UPDATE
   SET uncached_bytes_per_hour = EXCLUDED.uncached_bytes_per_hour,
       upstream_requests_per_hour = EXCLUDED.upstream_requests_per_hour,
       version = limit_ceiling.version + 1, updated_at = now(), updated_by = EXCLUDED.updated_by
`

type UpsertLimitCeilingParams struct {
	RepositoryID            int64
	Class                   string
	UncachedBytesPerHour    int64
	UpstreamRequestsPerHour int64
	Actor                   string
}

func (q *Queries) UpsertLimitCeiling(ctx context.Context, arg UpsertLimitCeilingParams) error {
	_, err := q.db.Exec(ctx, upsertLimitCeiling,
		arg.RepositoryID,
		arg.Class,
		arg.UncachedBytesPerHour,
		arg.UpstreamRequestsPerHour,
		arg.Actor,
	)
	return err
}

const upsertLimitProjectMaximum = `-- name: UpsertLimitProjectMaximum :execrows
INSERT INTO limit_project_maximum (project_id, profile_id, overrides, updated_by)
SELECT $1::text::uuid, p.id, $2::text::jsonb, NULLIF($3::text, '')::uuid
  FROM limit_profile p WHERE p.key = $4
ON CONFLICT (project_id) DO UPDATE
   SET profile_id = EXCLUDED.profile_id, overrides = EXCLUDED.overrides, version = limit_project_maximum.version + 1,
       updated_at = now(), updated_by = EXCLUDED.updated_by
 WHERE limit_project_maximum.version = $5
`

type UpsertLimitProjectMaximumParams struct {
	ProjectID string
	Overrides string
	Actor     string
	Profile   string
	Version   int64
}

// Sets or replaces a project's maximum; version 0 creates, any other replaces when it matches.
func (q *Queries) UpsertLimitProjectMaximum(ctx context.Context, arg UpsertLimitProjectMaximumParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertLimitProjectMaximum,
		arg.ProjectID,
		arg.Overrides,
		arg.Actor,
		arg.Profile,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
